"""Build the four plain HTML entry points. No Node build step is needed."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
brand='''<a class="brand" href="/"><svg viewBox="0 0 50 40" fill="none" aria-hidden="true"><path d="M3 7h28v23H3zM31 15h9l7 9v6H31" stroke="currentColor" stroke-width="3"/><path d="M8 13h17M8 19h12" stroke="#ef963b" stroke-width="3"/><circle cx="12" cy="32" r="5" fill="#ef963b"/><circle cx="38" cy="32" r="5" fill="#ef963b"/></svg><span>Qaz<b>Cargo</b><small data-t="brandSub"></small></span></a>'''
language='<select class="language" aria-label="Тіл / Язык / Language"><option value="kk">Қазақша</option><option value="ru">Русский</option><option value="en">English</option></select>'
dialogs=''.join(f'''<dialog id="{name}" class="dialog"><header class="dialog-header"><h2 class="dialog-title"></h2><button type="button" class="dialog-close" aria-label="Жабу / Закрыть / Close">×</button></header><div class="dialog-body"></div></dialog>''' for name in ('dialog','form-dialog','search-dialog'))
header=f'''<header class="site-header"><div class="container">{brand}<nav class="site-nav"><a href="/track" data-t="tracking"></a><a href="/#route-map" data-t="routeMap"></a><a href="/#routes" data-t="routes"></a><a href="/#services" data-t="services"></a><a href="/#how" data-t="how"></a></nav><div class="header-actions">{language}<a class="button small light" href="/login" data-t="login"></a><button class="mobile-menu" type="button" aria-label="Меню" aria-expanded="false">☰</button></div></div></header>'''
def page(body,script,title='QazCargo',kind=''):
    return f'''<!doctype html><html lang="kk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="QazCargo — Қазақстан қалалары арасындағы жүк тасымалын басқару"><title>{title}</title><link rel="stylesheet" href="/static/styles.css"></head><body data-page="{kind}">{body}<div id="toast" class="toast" role="status" aria-live="polite"></div>{dialogs}<script type="module" src="/static/{script}"></script></body></html>'''
home=header+'''<main><section class="hero"><div class="container"><div class="eyebrow" data-t="heroTag"></div><h1 data-t="heroTitle"></h1><p data-t="heroText"></p><a class="button accent" href="#calculator" data-t="request"></a></div><div class="hero-index">01 / QAZCARGO</div></section>
<section class="calculator container" id="calculator"><div class="calc-title"><h2 data-t="calculator"></h2><span class="eyebrow">QAZCARGO · KZT</span></div><form id="calculator-form"><div class="calc-grid"><div id="calculator-route"></div><label><span data-t="tariff"></span><select name="TariffID" required></select></label><label><span data-t="weight"></span><input name="WeightKg" type="number" min="0.01" step="0.01" value="100" required></label><button type="submit" data-t="calculate"></button></div><div id="estimate" class="calc-result" hidden></div></form></section>
<section class="section container" id="route-map"><div id="route-map-widget"></div></section>
<section class="section container" id="routes"><div class="section-heading"><div><div class="eyebrow">01 / <span data-t="routes"></span></div><h2 data-t="routesTitle"></h2></div><p data-t="routesText"></p></div><div class="route-grid" id="route-cards"></div><p class="notice" data-t="demoNotice" style="margin-top:22px"></p></section>
<section class="section service-band" id="services"><div class="container"><div class="section-heading"><div><div class="eyebrow">02 / <span data-t="services"></span></div><h2 data-t="fleetTitle"></h2></div></div><div class="cards">'''+''.join(f'<article class="card"><span class="number">0{i}</span><h3 data-t="service{i}"></h3><p data-t="service{i}Text"></p></article>' for i in range(1,4))+'''</div></div></section>
<section class="section container" id="how"><div class="section-heading"><h2 data-t="how"></h2></div><div class="cards">'''+''.join(f'<article class="card"><span class="number">0{i} →</span><h3 data-t="how{i}"></h3><p data-t="how{i}Text"></p></article>' for i in range(1,4))+'''</div></section></main>'''+f'''<footer class="site-footer"><div class="container">{brand}<p data-t="demoNotice"></p><a href="/login?role=admin" data-t="adminLogin"></a></div></footer>'''
(ROOT/'web/index.html').write_text(page(home,'public.js',kind='home'),encoding='utf-8')
login=header+'''<main class="login-layout"><section class="login-visual"><div class="eyebrow" data-t="heroTag"></div><h1 data-t="heroTitle"></h1><p data-t="loginText"></p></section><section class="login-panel"><div class="login-box"><h2 data-t="welcome"></h2><p class="muted" data-t="loginText"></p><div id="auth-form"></div><p class="notice" data-t="adminSetup"></p></div></section></main>'''
(ROOT/'web/login.html').write_text(page(login,'public.js',kind='login'),encoding='utf-8')
for role,file in [('admin','admin'),('client','customer')]:
    shell=f'''<div class="app-layout"><aside class="sidebar">{brand}<div class="role-label" data-t="{role}"></div><nav id="sidebar-nav"></nav><button class="logout" id="logout" data-t="logout"></button></aside><div class="workspace"><header class="app-header"><div class="header-actions"><button class="mobile-menu" type="button" aria-label="Меню" aria-expanded="false">☰</button><h1 id="page-title"></h1></div><div class="header-actions"><span class="user-chip" id="user-name"></span><button id="notification-button" disabled class="small light notification-button" type="button"><span data-t="notifications"></span><span id="notification-count" class="notification-count" hidden>0</span></button><button class="small light" id="refresh" data-t="refresh"></button>{language}</div></header><div class="workspace-tools"><button type="button" id="global-search-button" class="light" disabled><span data-t="globalSearch"></span><kbd>Ctrl K</kbd></button><nav class="breadcrumbs" aria-label="Navigation"><button type="button" id="breadcrumb-home" data-t="dashboard"></button><span aria-hidden="true">/</span><span id="breadcrumb-current"></span></nav></div><main class="app-main" id="content"><p data-t="loading"></p></main></div></div>'''
    (ROOT/f'web/{file}.html').write_text(page(shell,'workspace.js','QazCargo — '+('Әкімші' if role=='admin' else 'Клиент'),role),encoding='utf-8')

tracking=header+'''<main class="container tracking-page"><div class="tracking-heading"><span class="eyebrow">QAZCARGO / TRACKING</span><h1 data-t="trackingHeading"></h1><p data-t="trackingIntro"></p></div><form id="tracking-form" class="panel tracking-form"><label><span data-t="trackingCode"></span><input id="tracking-code" name="code" type="text" required maxlength="64" minlength="64" pattern="[a-fA-F0-9]{64}" autocomplete="off" spellcheck="false"></label><button type="submit" data-t="tracking"></button></form><div id="tracking-result" aria-live="polite"></div></main>'''
(ROOT/'web/track.html').write_text(page(tracking,'tracking.js','QazCargo — Tracking','tracking'),encoding='utf-8')
